const BIG_NUMBERS_CARD_NAVIGATION_SLUGS = new Set(['volume', 'net-revenue']);
const BIG_NUMBERS_CARD_DESCRIPTION_KPIS = new Set(['volume', 'nr']);

export const usesPerformanceToolBigNumbersCardNavigation = (
  kpiSlug: string,
  usesTimePeriod: boolean,
): boolean => usesTimePeriod && BIG_NUMBERS_CARD_NAVIGATION_SLUGS.has(kpiSlug);

export const usesPerformanceToolBigNumbersCardDescriptions = (
  kpi: string,
): boolean => BIG_NUMBERS_CARD_DESCRIPTION_KPIS.has(kpi);
